async fn handle_payment_event(event: PaymentEvent, db: &Database) {
    // Query local database message tracker for duplicates first
    if db.is_message_already_processed(&event.msg_id).await.unwrap_or(false) {
        return; // Safe discard of duplicate message
    }

    let mut account = db.find_account(event.user_id).await.unwrap();
    account.balance -= event.amount;
    db.save_and_mark_processed(account, &event.msg_id).await.unwrap();
}
